package sandbox
import (
 "context"
 "fmt"
 "testing"
 "time"
)
func TestInventoryTheoryCounterexamples(t *testing.T) {
 config := func() Config { return Config{Mode:"warm", Concurrency:1, WarmPoolSize:3, DynamicWarmPool:true, WarmMinSize:1, WarmMaxSize:3, MaxSandboxes:4, CreateConcurrency:1, QueueSize:16, QueueBytes:1024, QueueTimeout:time.Second, WarmAdjustInterval:time.Second, WarmIdleFor:30*time.Second} }
 t.Run("queue_waiting_for_execution_slot",func(t *testing.T) {
  c:=config();c.WarmMinSize=2
  p:=newWarmPool(c,nil,nil);defer p.cancel();p.initialized=true
  a,b,active:=&executionState{id:"ready-a"},&executionState{id:"ready-b"},&executionState{id:"leased"}
  p.ready=[]*executionState{a,b};p.items[a]=poolReady;p.items[b]=poolReady;p.items[active]=poolRunning;p.executing=1
  p.waiters=[]*poolWaiter{{enteredAt:time.Now(),bytes:1}};p.queuedBytes=1
  p.inventory.LastChange=time.Now().Add(-2*time.Second)
  p.adjustInventoryLocked(time.Now())
  if p.inventory.Target!=3 {t.Fatalf("unexpected target: %d",p.inventory.Target)}
  t.Logf("ready=%d executing=%d execution_limit=%d queued=%d target_before=2 target_after=%d",len(p.ready),p.executing,c.Concurrency,len(p.waiters),p.inventory.Target)
 })
 t.Run("sparse_requests_without_inventory_wait",func(t *testing.T) {
  c:=config();p:=newWarmPool(c,nil,nil);defer p.cancel();p.initialized=true
  origin:=time.Now();p.inventory.LastChange=origin
  id:=0
  refill:=func(){for len(p.ready)<p.inventory.Target {id++;x:=&executionState{id:fmt.Sprint(id)};p.ready=append(p.ready,x);p.items[x]=poolReady}}
  refill()
  for request:=1;request<=3;request++ {
   at:=origin.Add(time.Duration(request)*10*time.Second)
   before:=p.inventory.Target
   x,err:=p.acquire(context.Background(),1);if err!=nil {t.Fatal(err)}
   p.mark(x,poolDestroying);p.release(x,true)
   refill() // successful replacement before decision; no queue or active work remains
   readyBefore:=len(p.ready)
   p.adjustInventoryLocked(at)
   refill()
   p.adjustInventoryLocked(at.Add(time.Millisecond)) // establish idle baseline
   t.Logf("request=%d logical_gap=10s ready_before_decision=%d queued=%d executing=%d target_before=%d target_after=%d",request,readyBefore,len(p.waiters),p.executing,before,p.inventory.Target)
  }
  if p.inventory.Target!=3 || p.telemetry.QueueEntered!=0 || p.inventory.ScaleUps!=2 {t.Fatalf("unexpected state: %+v",p.inventory)}
 })
}
